/**
 * Shared helpers/constants for the Worker request handler.
 *
 * IMPORTANT (Cloudflare Workers module format): the *entry* module
 * (`src/worker/index.js`) must only have a default export. workerd treats every
 * named export of the entry module as an additional service entrypoint and
 * rejects values that are not functions/`ExportedHandler` objects, e.g.
 *
 *   service core:user:zurich-maps: Uncaught TypeError:
 *   Incorrect type for map entry 'VERSION': the provided value is not of type
 *   'function or ExportedHandler'.
 *
 * So everything that is worth unit-testing but is not the handler lives here,
 * and `index.js` merely imports it. Keep it that way.
 */

export const VERSION = '0.2.0';

/** Hosts the proxy may talk to, and the path prefixes allowed per host. */
export const ALLOWLIST = [
  { host: 'api3.geo.admin.ch', prefixes: ['/rest/services/api/SearchServer'] },
  { host: 'www.e-rara.ch', prefixes: ['/i3f/', '/zuz/oai', '/oai'] },
  { host: 'wmts.geo.admin.ch', prefixes: ['/1.0.0/', '/EPSG/'] },
  { host: 'data.geo.admin.ch', prefixes: ['/'] },
];

export const USER_AGENT =
  'zurich-maps/0.2 (+https://github.com/igor-makarov/maps-n-stuff; historical map explorer)';

export const HTML_ESCAPE = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

export function json(body, init = {}) {
  return new Response(JSON.stringify(body, null, 1), {
    ...init,
    headers: { 'content-type': 'application/json; charset=utf-8', ...(init.headers || {}) },
  });
}

export function isAllowed(target) {
  if (target.protocol !== 'https:') return false;
  const rule = ALLOWLIST.find((r) => r.host === target.hostname);
  if (!rule) return false;
  return rule.prefixes.some((p) => target.pathname.startsWith(p));
}

export async function upstream(url, { accept = '*/*', timeoutMs = 8000 } = {}) {
  return fetch(url, {
    headers: { 'user-agent': USER_AGENT, accept },
    signal: AbortSignal.timeout(timeoutMs),
    redirect: 'follow',
  });
}

/** Strip simple HTML markup/tags that swisstopo includes in search labels. */
export function stripTags(value) {
  return String(value ?? '').replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();
}

/** Parse swisstopo's `BOX(west south,east north)` geometry string. */
export function parseBox(box2d) {
  const box = String(box2d ?? '').match(/BOX\(([-\d.eE]+) ([-\d.eE]+),([-\d.eE]+) ([-\d.eE]+)\)/);
  if (!box) return null;
  const [west, south, east, north] = [box[1], box[2], box[3], box[4]].map(Number);
  if (![west, south, east, north].every(Number.isFinite)) return null;
  if (west >= east || south >= north) return null;
  return { west, south, east, north };
}

