/**
 * Minimal Chrome DevTools Protocol driver (no dependencies) used to smoke-test
 * the rendered application: console errors, failed requests, DOM assertions,
 * screenshots. Usage:
 *
 *   node /tmp/cdp.mjs <url> [--out shot.png] [--width 1440] [--height 900]
 *                              [--wait 5000] [--script 'js to evaluate']
 */
import { spawn } from 'node:child_process';
import { writeFileSync, mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';

const args = process.argv.slice(2);
const url = args[0];
const opt = (name, fallback) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 ? args[i + 1] : fallback;
};
const width = Number(opt('width', 1440));
const height = Number(opt('height', 900));
const waitMs = Number(opt('wait', 5000));
const out = opt('out', null);
const extraScript = opt('script', null);
const port = Number(opt('port', 9333));

const profile = mkdtempSync(path.join(tmpdir(), 'cdp-'));
const chrome = spawn(
  'chromium',
  [
    `--remote-debugging-port=${port}`,
    `--user-data-dir=${profile}`,
    '--headless=new',
    '--no-sandbox',
    '--disable-gpu',
    '--hide-scrollbars',
    '--no-first-run',
    '--disable-dev-shm-usage',
    'about:blank',
  ],
  { stdio: 'ignore' },
);

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function findTarget() {
  for (let i = 0; i < 60; i += 1) {
    try {
      const res = await fetch(`http://127.0.0.1:${port}/json/list`);
      const list = await res.json();
      const page = list.find((t) => t.type === 'page');
      if (page?.webSocketDebuggerUrl) return page.webSocketDebuggerUrl;
    } catch {
      /* not up yet */
    }
    await sleep(250);
  }
  throw new Error('chromium devtools endpoint never appeared');
}

const wsUrl = await findTarget();
const ws = new WebSocket(wsUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true });
  ws.addEventListener('error', reject, { once: true });
});

let nextId = 1;
const pending = new Map();
const consoleMessages = [];
const exceptions = [];
const failedRequests = [];
const responses = [];

ws.addEventListener('message', (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(JSON.stringify(msg.error)));
    else resolve(msg.result);
    return;
  }
  if (msg.method === 'Runtime.consoleAPICalled') {
    consoleMessages.push({
      level: msg.params.type,
      text: msg.params.args.map((a) => a.value ?? a.description ?? a.type).join(' '),
    });
  } else if (msg.method === 'Runtime.exceptionThrown') {
    const d = msg.params.exceptionDetails;
    exceptions.push(`${d.exception?.description ?? d.text} @ ${d.url ?? ''}:${d.lineNumber}`);
  } else if (msg.method === 'Network.loadingFailed') {
    if (!/net::ERR_ABORTED/.test(msg.params.errorText ?? '')) {
      failedRequests.push({ url: msg.params.requestId, error: msg.params.errorText, type: msg.params.type });
    }
  } else if (msg.method === 'Network.responseReceived') {
    const r = msg.params.response;
    if (r.status >= 400) responses.push({ status: r.status, url: r.url });
  } else if (msg.method === 'Network.requestWillBeSent') {
    const id = msg.params.requestId;
    pendingUrls.set(id, msg.params.request.url);
  }
});

const pendingUrls = new Map();
function send(method, params = {}) {
  const id = nextId++;
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
}

await send('Runtime.enable');
await send('Log.enable');
await send('Network.enable');
await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url });
await sleep(waitMs);

const evaluate = async (expression) => {
  const res = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (res.exceptionDetails) return { error: res.exceptionDetails.text };
  return res.result.value;
};

const summary = await evaluate(`(() => {
  const q = (s) => document.querySelector(s);
  const tiles = [...document.querySelectorAll('.map-tile')];
  const imgs = [...document.querySelectorAll('img')];
  return {
    title: document.title,
    results: document.querySelectorAll('#result-list li').length,
    resultCountText: q('#result-count')?.textContent ?? null,
    markers: document.querySelectorAll('.map-marker').length,
    tiles: tiles.length,
    brokenTiles: tiles.filter((t) => t.dataset.failed === 'true').length,
    brokenImages: imgs.filter((i) => i.complete && i.naturalWidth === 0 && i.getAttribute('src')).length,
    totalImages: imgs.length,
    stateHidden: q('#results-state')?.hidden ?? null,
    stateText: q('#results-state')?.textContent?.slice(0, 120) ?? null,
    mapFallback: q('#map-fallback')?.outerHTML?.slice(0, 80) ?? null,
    modules: null,
    overlayOptions: q('#overlay-select')?.options?.length ?? null,
    providerFilters: document.querySelectorAll('#provider-filters input').length,
    yearFrom: q('#year-from')?.value ?? null,
    yearTo: q('#year-to')?.value ?? null,
    detailHidden: q('#detail')?.hidden ?? null,
  };
})()`);

const log = await evaluate(`[...document.querySelectorAll('.zh-suggestions')].length`);

console.log(JSON.stringify({
  url,
  summary,
  consoleMessages,
  exceptions,
  failedRequests: failedRequests.map((f) => ({ ...f, url: pendingUrls.get(f.url) ?? f.url })),
  errorResponses: responses.slice(0, 20),
}, null, 2));

if (extraScript) {
  const result = await evaluate(extraScript);
  console.log('--- script result ---');
  console.log(JSON.stringify(result, null, 2));
}

if (out) {
  const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
  writeFileSync(out, Buffer.from(shot.data, 'base64'));
  console.log(`screenshot written: ${out}`);
}

ws.close();
chrome.kill('SIGKILL');
process.exit(0);

