clampYear(undefined) → Number(undefined)=NaN → returns years.min. Guard for missing inputs: if (!yearFrom || !yearTo) skip.

2. Edition selection tied to the active year range:
```js
  /** Choose the edition closest to (and not after) a publication year. */
  function editionForYear(layer, year) {
    const values = editionsOf(layer);
    if (values.length === 0) return '';
    const yearOf = (v) => Number(String(v).slice(0, 4)) || null;
    let best = values[0];
    for (const v of values) {
      const y = yearOf(v);
      if (y !== null && y <= year) best = v;
    }
    // if all editions are later than the filter, use the oldest
    return best ?? values[0];
  }
